    fn fixed_numbers(&mut self,count:usize)->Result<FieldValue,TextError>{let mut values=Vec::new();for index in 0..count{if index!=0{self.expect(TokenKind::Comma)?;}let(value,_)=self.number()?;self.push(&mut values,FieldValue::Float(value))?;}if self.kind()?==TokenKind::Comma{return Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"native coordinate arity mismatch"));}Ok(FieldValue::Tuple(values))}
    fn table(&mut self,make:RecordSpecProducer,depth:usize)->Result<FieldValue,TextError>{
        let spec=self.metadata(&make)?;validate_table_columns(&spec)?;self.expect(TokenKind::LBracket)?;let mut columns=Vec::new();while self.kind()?!=TokenKind::RBracket{let token=self.expect(TokenKind::Ident)?;let field=spec.fields.iter().find(|field|field.key==token.text).ok_or_else(||self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"unknown native table column"))?;if columns.iter().any(|column:&&FieldSpec|column.id==field.id){return Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"duplicate native table column"));}if self.kind()?==TokenKind::Colon{self.take()?;self.expect(TokenKind::Ident)?;}self.push(&mut columns,field)?;}self.take()?;self.expect(TokenKind::LBrace)?;let mut rows=Vec::new();while self.kind()?!=TokenKind::RBrace{if columns.is_empty(){return Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"native table requires columns"));}self.node(depth)?;let mut record=RecordValue::default();for field in &columns{let value=if self.kind()?==TokenKind::Placeholder{self.take()?;FieldValue::Absent}else if let Shape::Record(make)=field.shape{self.expect(TokenKind::LBrace)?;let record={let spec=self.metadata(&make)?;self.record(&spec,depth+1)?};self.expect(TokenKind::RBrace)?;FieldValue::Record(record)}else{self.shape(&field.shape,depth+1)?};self.insert(&mut record,field.id,value)?;}for field in &spec.fields{if !record.fields.contains_key(&field.id){self.insert(&mut record,field.id,FieldValue::Absent)?;}}self.push(&mut rows,FieldValue::Record(record))?;}self.take()?;Ok(FieldValue::List(rows))
