    fn dynamic(&mut self,depth:usize)->Result<DslValue,TextError>{
        self.node(depth)?;let token=self.peek(0)?;match token.kind{
            TokenKind::LBrace=>{self.take()?;let mut entries=Vec::new();while let Some(key)=self.dynamic_key()?{let key=self.text(key)?;self.take()?;self.expect(TokenKind::Equals)?;let value=self.dynamic(depth+1)?;self.push(&mut entries,(key,value))?;}self.expect(TokenKind::RBrace)?;Ok(DslValue::Object(entries))},
            TokenKind::LBracket=>{self.take()?;let mut values=Vec::new();while self.kind()?!=TokenKind::RBracket{let value=self.dynamic(depth+1)?;self.push(&mut values,value)?;}self.take()?;Ok(DslValue::Array(values))},
            TokenKind::Text=>{self.take()?;self.text(token).map(DslValue::String)},
            TokenKind::Int=>{self.take()?;if token.text.len()>2048{return Err(self.error(semio_framework_value::ValueRefusalKind::WorkLimit,"native dynamic integer is too long"));}let value=if let Ok(value)=token.text.parse::<u64>(){Number::UInt(value)}else if let Ok(value)=token.text.parse::<i64>(){Number::Int(value)}else{Number::Float(parse_f64(token.text).map_err(|_|self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"invalid native dynamic number"))?)};Ok(DslValue::Number(value))},
            TokenKind::Float=>self.number().map(|(value,_)|DslValue::Number(Number::Float(value))),
            TokenKind::Ident=>{self.take()?;match token.text{"null"=>Ok(DslValue::Null),"true"=>Ok(DslValue::Bool(true)),"false"=>Ok(DslValue::Bool(false)),"nan"|"inf"=>parse_f64(token.text).map(|value|DslValue::Number(Number::Float(value))).map_err(|_|self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"invalid native dynamic number")),"int64"=>{self.expect(TokenKind::LParen)?;let token=self.expect(TokenKind::Int)?;if token.text.len()>21{return Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"native signed integer is out of range"))}let value=token.text.parse::<i64>().map_err(|_|self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"invalid native signed integer"))?;self.expect(TokenKind::RParen)?;Ok(DslValue::Number(Number::Int(value)))},"bytes64"=>{self.expect(TokenKind::LParen)?;let token=self.expect(TokenKind::Text)?;let bytes=self.octets(token)?;self.expect(TokenKind::RParen)?;Ok(DslValue::Bytes(bytes))},_=>Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"unknown native dynamic literal"))}},
            _=>Err(self.error(semio_framework_value::ValueRefusalKind::InvalidValue,"invalid native dynamic value"))
